<?php
require_once __DIR__.'/../../includes/bootstrap.php';require_roles(['ADMIN','RESPONSABLE','AGENT']);$db=Database::connection();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$cid=(int)$_POST['contrat_id'];$s=$db->prepare('SELECT prime_annuelle FROM contrats WHERE id=?');$s->execute([$cid]);$prime=(float)$s->fetchColumn();$db->prepare("INSERT INTO renouvellements(contrat_id,date_lancement,ancienne_prime,statut) VALUES(?,CURRENT_DATE,?,'planifie')")->execute([$cid,$prime]);audit('PLANIFICATION','renouvellement',(int)$db->lastInsertId());redirect('renouvellements/index.php');}$contracts=$db->query("SELECT c.id,c.numero_police,c.date_echeance FROM contrats c WHERE c.statut='actif' AND NOT EXISTS(SELECT 1 FROM renouvellements r WHERE r.contrat_id=c.id AND r.statut<>'annule') ORDER BY c.date_echeance")->fetchAll();$rows=$db->query("SELECT r.*,c.numero_police,c.date_echeance FROM renouvellements r JOIN contrats c ON c.id=r.contrat_id ORDER BY c.date_echeance")->fetchAll();$title='Renouvellements';require __DIR__.'/../../includes/header.php';?>
<div class="page-heading"><div><h1 class="h3">Renouvellements</h1><p class="text-secondary">Planification et re-comparaison des contrats</p></div></div><?php if($contracts): ?><form method="post" class="card card-body mb-3"><?= csrf_field() ?><div class="d-flex gap-2"><select class="form-select" name="contrat_id"><?php foreach($contracts as $c): ?><option value="<?= $c['id'] ?>"><?= e($c['numero_police'].' · échéance '.$c['date_echeance']) ?></option><?php endforeach ?></select><button class="btn btn-primary">Planifier</button></div></form><?php endif; ?><div class="card"><table class="table mb-0"><thead><tr><th>Police</th><th>Échéance</th><th>Ancienne prime</th><th>Décision</th><th>Statut</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= e($r['numero_police']) ?></td><td><?= e($r['date_echeance']) ?></td><td><?= number_format((float)$r['ancienne_prime'],0,',',' ') ?> FCFA</td><td><?= e($r['decision_client']) ?></td><td><?= e($r['statut']) ?></td></tr><?php endforeach ?></tbody></table></div><?php require __DIR__.'/../../includes/footer.php'; ?>
